// Command gen walks the parent package at `go generate` time, reads the
// `check` tag off every struct field, and emits a per-type Validate method.
// The output has no reflection: each check is inlined for that type.
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"log"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"
)

func main() {
	dir := "."
	if len(os.Args) > 1 {
		dir = os.Args[1]
	}
	abs, _ := filepath.Abs(dir)

	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, abs, func(fi os.FileInfo) bool {
		// Skip the generated file itself.
		return !strings.HasSuffix(fi.Name(), "_check.go")
	}, 0)
	if err != nil {
		log.Fatal(err)
	}

	for _, pkg := range pkgs {
		var body bytes.Buffer
		wrote := 0
		for _, file := range pkg.Files {
			ast.Inspect(file, func(n ast.Node) bool {
				ts, ok := n.(*ast.TypeSpec)
				if !ok {
					return true
				}
				st, ok := ts.Type.(*ast.StructType)
				if !ok {
					return true
				}
				if emitValidate(&body, ts.Name.Name, st) {
					wrote++
				}
				return true
			})
		}

		if wrote == 0 {
			continue
		}

		var buf bytes.Buffer
		fmt.Fprintln(&buf, "// Code generated by gen-check; DO NOT EDIT.")
		fmt.Fprintf(&buf, "package %s\n\n", pkg.Name)
		fmt.Fprintln(&buf, `import (`)
		fmt.Fprintln(&buf, `	"errors"`)
		fmt.Fprintln(&buf, `	"fmt"`)
		fmt.Fprintln(&buf, `	"net/mail"`)
		fmt.Fprintln(&buf, `)`)
		fmt.Fprintln(&buf)
		buf.Write(body.Bytes())

		out := filepath.Join(abs, "zz_generated_check.go")
		formatted, err := format.Source(buf.Bytes())
		if err != nil {
			log.Fatalf("format generated code: %v\n%s", err, buf.String())
		}
		if err := os.WriteFile(out, formatted, 0644); err != nil {
			log.Fatal(err)
		}
		fmt.Printf("wrote %s (%d types)\n", out, wrote)
	}
}

// emitValidate writes a Validate method for one struct if any field has a
// `check` tag. It returns true when a method was emitted.
func emitValidate(buf *bytes.Buffer, name string, st *ast.StructType) bool {
	type check struct {
		field, op, arg string
	}
	var checks []check

	for _, f := range st.Fields.List {
		if f.Tag == nil || len(f.Names) == 0 {
			continue
		}
		raw, err := strconv.Unquote(f.Tag.Value)
		if err != nil {
			continue
		}
		tag := reflect.StructTag(raw).Get("check")
		if tag == "" {
			continue
		}
		for _, r := range strings.Split(tag, ",") {
			head, arg, _ := strings.Cut(r, "=")
			checks = append(checks, check{f.Names[0].Name, head, arg})
		}
	}

	if len(checks) == 0 {
		return false
	}

	recv := strings.ToLower(string(name[0]))
	fmt.Fprintf(buf, "func (%s *%s) Validate() error {\n", recv, name)
	for _, c := range checks {
		switch c.op {
		case "required":
			fmt.Fprintf(buf, "\tif %s.%s == \"\" {\n", recv, c.field)
			fmt.Fprintf(buf, "\t\treturn errors.New(%q)\n", c.field+": required")
			fmt.Fprintln(buf, "\t}")
		case "min":
			fmt.Fprintf(buf, "\tif len(%s.%s) < %s {\n", recv, c.field, c.arg)
			fmt.Fprintf(buf, "\t\treturn errors.New(%q)\n", fmt.Sprintf("%s: min %s", c.field, c.arg))
			fmt.Fprintln(buf, "\t}")
		case "email":
			fmt.Fprintf(buf, "\tif _, err := mail.ParseAddress(%s.%s); err != nil {\n", recv, c.field)
			fmt.Fprintf(buf, "\t\treturn fmt.Errorf(\"%s: %%w\", err)\n", c.field)
			fmt.Fprintln(buf, "\t}")
		}
	}
	fmt.Fprintln(buf, "\treturn nil")
	fmt.Fprintln(buf, "}")
	fmt.Fprintln(buf)
	return true
}
